package com.moments.assistant;
import android.app.*;import android.os.*;import android.content.*;import android.widget.*;import java.util.*;
public class TextListActivity extends Activity{
 public static void open(Context c,String mode){ Intent i=new Intent(c,TextListActivity.class); i.putExtra("mode",mode); c.startActivity(i); }
 @Override public void onCreate(Bundle b){super.onCreate(b); LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(20,20,20,20); TextView title=new TextView(this); title.setTextSize(24); String mode=getIntent().getStringExtra("mode"); boolean mat="materials".equals(mode); title.setText(mat?"素材库":"克隆历史"); root.addView(title); ScrollView sv=new ScrollView(this); LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL); ArrayList<String> data=mat?Store.materials(this):Store.history(this); if(data.isEmpty()){TextView e=new TextView(this);e.setText("暂无记录");e.setPadding(0,30,0,0);list.addView(e);} for(String s:data){TextView v=new TextView(this);v.setText(s);v.setTextSize(15);v.setPadding(16,18,16,18);v.setBackgroundColor(0xFFF4F4F5); LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,10,0,0); list.addView(v,p); if(!mat)v.setOnClickListener(x->{((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("朋友圈文案",s));Toast.makeText(this,"已复制",Toast.LENGTH_SHORT).show();}); } sv.addView(list);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));setContentView(root); }
}
